function bishkekDayKey(v){
  try{
    var d=v instanceof Date?v:new Date(v||'');
    if(isNaN(d.getTime()))return String(v||'').slice(0,10);
    var parts=new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Bishkek',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(d),m={};
    parts.forEach(function(x){if(x.type!=='literal')m[x.type]=x.value;});
    return (m.year||'0000')+'-'+(m.month||'00')+'-'+(m.day||'00');
  }catch(_){return String(v||'').slice(0,10);}
}
function dayHeaderLabel(key){
  var months=['ЯНВАРЯ','ФЕВРАЛЯ','МАРТА','АПРЕЛЯ','МАЯ','ИЮНЯ','ИЮЛЯ','АВГУСТА','СЕНТЯБРЯ','ОКТЯБРЯ','НОЯБРЯ','ДЕКАБРЯ'];
  if(key===bishkekDayKey(new Date()))return 'СЕГОДНЯ';
  var p=String(key||'').split('-'),m=Number(p[1]||0),d=Number(p[2]||0);
  return d&&m?d+' '+(months[m-1]||''):String(key||'');
}
function txDateGroups(list){
  var map={},order=[];(list||[]).forEach(function(x){var k=bishkekDayKey(x.created_at||x.updated_at||x.date||'');if(!map[k]){map[k]=[];order.push(k);}map[k].push(x);});
  return order.map(function(k){return {key:k,label:dayHeaderLabel(k),items:map[k]};});
}
function chatDayLabel(key){
  var today=bishkekDayKey(new Date()),y=new Date();y.setDate(y.getDate()-1);var yesterday=bishkekDayKey(y);
  if(key===today)return 'Сегодня';if(key===yesterday)return 'Вчера';
  var p=String(key||'').split('-'),months=['января','февраля','марта','апреля','мая','июня','июля','августа','сентября','октября','ноября','декабря'];
  return Number(p[2]||0)+' '+(months[Number(p[1]||1)-1]||'')+(String(p[0]||'')!==String(new Date().getFullYear())?' '+p[0]:'');
}
