   var t=r.tx||tx;
   self.setState({modal:'txEdit',modalData:{tx:t,profile:r.profile||null,editable:r.editable!==false,bookmakers:r.bookmakers||[],
     draft:{player_id:String(t.account_id||t.bookmaker_id||''),amount:String(Math.round(Number(t.kind==='deposit'?(t.amount||0):(t.amount||0)))||''),bookmaker:String(t.site||'')}}});
