/* === LUXON WEB PUSH CLIENT v1 === */
(function(){
  if(window.__luxPushClientV1)return;
  window.__luxPushClientV1=true;

  function b64ToU8(s){
    var p='='.repeat((4-s.length%4)%4);
    var b=(s+p).replace(/-/g,'+').replace(/_/g,'/');
    var raw=atob(b),a=new Uint8Array(raw.length);
    for(var i=0;i<raw.length;i++)a[i]=raw.charCodeAt(i);
    return a;
  }

  async function regWorker(){
    if(!('serviceWorker' in navigator))throw new Error('Service Worker не поддерживается');
    return navigator.serviceWorker.register('/sw.js',{scope:'/'});
  }

  async function syncSub(reg,ask){
    if(!('PushManager' in window))throw new Error('Push API не поддерживается');
    var perm=Notification.permission;
    if(perm==='default'&&ask)perm=await Notification.requestPermission();
    if(perm!=='granted')throw new Error(perm==='denied'?'Уведомления запрещены в настройках устройства':'Разрешение не выдано');

    var key=await api('/api/push/public-key');
    if(!key.available)throw new Error('Push-модуль сервера не запущен');

    var sub=await reg.pushManager.getSubscription();
    if(!sub){
      sub=await reg.pushManager.subscribe({
        userVisibleOnly:true,
        applicationServerKey:b64ToU8(key.public_key)
      });
    }

    await api('/api/push/subscribe',{method:'POST',body:{subscription:sub.toJSON()}});
    localStorage.setItem('lux_webpush_enabled','1');
    localStorage.setItem('lux_webpush_synced_at',String(Date.now()));
    return sub;
  }

  window.luxEnablePush=async function(ctx){
    var reg=await regWorker();
    var sub=await syncSub(reg,true);
    try{
      if(ctx&&ctx.setNotifyPref)ctx.setNotifyPref('enabled',true);
      if(ctx&&ctx.setState)ctx.setState({notificationPrompt:false});
      if(ctx&&ctx.toast)ctx.toast('Push-уведомления подключены');
    }catch(e){}
    try{await api('/api/push/test',{method:'POST',body:{}});}catch(e){}
    return sub;
  };

  async function silentSync(){
    try{
      if(typeof Notification==='undefined'||Notification.permission!=='granted')return;
      var reg=await regWorker();
      var sub=await reg.pushManager.getSubscription();
      if(!sub)return;
      await api('/api/push/subscribe',{method:'POST',body:{subscription:sub.toJSON()}});
      localStorage.setItem('lux_webpush_enabled','1');
      localStorage.setItem('lux_webpush_synced_at',String(Date.now()));
    }catch(e){}
  }

  if(typeof App!=='undefined'&&App.prototype){
    App.prototype.requestNotifications=function(){
      var self=this;
      window.luxEnablePush(this).catch(function(err){
        try{self.toast(err.message||'Не удалось подключить push');}catch(e){}
      });
    };
  }

  if(document.readyState==='loading'){
    document.addEventListener('DOMContentLoaded',silentSync,{once:true});
  }else{
    silentSync();
  }

  setInterval(function(){
    var last=Number(localStorage.getItem('lux_webpush_synced_at')||0);
    if(Date.now()-last>21600000)silentSync();
  },900000);
})();
/* === /LUXON WEB PUSH CLIENT v1 === */



/* === LUXON THEME V2 === */
(function(){
  var KEY='lux-admin-theme-v1';
  var mq=(window.matchMedia?window.matchMedia('(prefers-color-scheme: dark)'):null);
  function mode(){
    try{var v=localStorage.getItem(KEY);return (v==='light'||v==='dark'||v==='system')?v:'system';}catch(e){return 'system';}
  }
  function effective(v){v=v||mode();return v==='system'?(mq&&mq.matches?'dark':'light'):v;}
  function apply(v,persist){
    if(v!=='light'&&v!=='dark'&&v!=='system')v='system';
    if(persist!==false){try{localStorage.setItem(KEY,v);}catch(e){}}
    var e=effective(v),root=document.documentElement;
    root.setAttribute('data-theme',e);root.setAttribute('data-theme-mode',v);root.style.colorScheme=e;
    var meta=document.querySelector('meta[name="theme-color"]');if(meta)meta.setAttribute('content',e==='dark'?'#0E1621':'#f4f7f8');
    return e;
  }
  function onSystem(){if(mode()==='system')apply('system',false);}
  if(mq){try{mq.addEventListener('change',onSystem);}catch(_){try{mq.addListener(onSystem);}catch(__){}}}
  window.luxGetTheme=function(){return effective(mode());};
  window.luxGetThemeMode=mode;
  window.luxSetThemeMode=function(v){return apply(v,true);};
  window.luxSetTheme=function(v){return apply(v,true);};
  window.luxToggleTheme=function(){return apply(effective(mode())==='dark'?'light':'dark',true);};
  apply(mode(),false);
})();
/* === /LUXON THEME V2 === */




/* === LUXON IOS NO DOUBLE TAP ZOOM V1 === */
(function(){
  if(window.__luxNoDoubleTapZoomV1)return;
  window.__luxNoDoubleTapZoomV1=true;

  var lastTouchEnd=0;

  document.addEventListener('touchend',function(e){
    var now=Date.now();
    if(now-lastTouchEnd<=320){
      var t=e.target;
      var editable=t && (
        t.tagName==='INPUT' ||
        t.tagName==='TEXTAREA' ||
        t.tagName==='SELECT' ||
        t.isContentEditable
      );
      if(!editable){
        e.preventDefault();
      }
    }
    lastTouchEnd=now;
  },{passive:false});

  document.addEventListener('gesturestart',function(e){
    e.preventDefault();
  },{passive:false});

  document.addEventListener('dblclick',function(e){
    var t=e.target;
    var editable=t && (
      t.tagName==='INPUT' ||
      t.tagName==='TEXTAREA' ||
      t.tagName==='SELECT' ||
      t.isContentEditable
    );
    if(!editable)e.preventDefault();
  },{passive:false});
})();
/* === /LUXON IOS NO DOUBLE TAP ZOOM V1 === */

